/* Compact wallet workspace. All amounts, eligibility and transfers are server-authoritative. */
window.MioWalletHub=(()=>{
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=v=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:4});
 const kinds=[['proceed','Proceed Wallet','proceed_mio'],['cash','Cash Wallet','cash_mio'],['promotion','Promotion Points','promotion_points'],['shopping','Shopping Points','shopping_points']];
 let api,history,uid=null,kind='proceed',wallets=null,platinum=false,historyOpen=false,busy=false,epoch=0,lookupTurn=0,recipient=null,lookupTimer,requestKey=null,transferKey=null,transferSignature='';
 function setIdentity(id){if(uid===id)return;uid=id;epoch++;lookupTurn++;clearTimeout(lookupTimer);recipient=null;wallets=null;historyOpen=false;kind='proceed';$('walletHubStatement')?.setAttribute('hidden','');requestKey=null;transferKey=null;busy=false;history?.setIdentity(id);if(id)history?.setWallet(kind);$('walletTransferDialog')?.close();$('walletTransferForm')?.reset();$('incomeWalletCards')?.replaceChildren();$('walletHubMessage')?.replaceChildren()}
 function ensure(){const root=$('incomeWalletHub');if(!root)return false;if(!$('incomeWalletCards')){root.innerHTML='<div id="incomeWalletCards" class="wallet-hub-cards"></div><p id="walletHubMessage" class="wallet-hub-message" role="status" hidden></p><section id="walletHubStatement" class="card wallet-hub-history" hidden><div id="walletHubHistory"></div></section>';history=window.createMioWalletHistory({compact:true,host:()=>$('walletHubHistory')});history.mount({rpc:api.rpc,error:e=>message(e.message)});history.setIdentity(uid);history.setWallet(kind)}return true}
 function message(text){const target=$('walletHubMessage');if(target){target.hidden=!text;target.textContent=text||''}}
 function cards(){if(!wallets||!ensure())return;$('incomeWalletCards').innerHTML=kinds.map(([key,label,field])=>`<article class="wallet-hub-card wallet-hub-${key} ${historyOpen&&key===kind?'selected':''}"><div class="wallet-hub-card-top"><h2>${label}</h2><span class="wallet-hub-icon" aria-hidden="true">${window.MioDashboard?.icon(key==='shopping'?'bag':key==='promotion'?'diamond':'wallet')||''}</span></div><div class="wallet-hub-balance"><strong>${fmt(wallets[field])}</strong> <span>${['shopping','promotion'].includes(key)?'POINTS':'MIO'}</span></div><div class="wallet-hub-card-footer"><button type="button" class="wallet-hub-select wallet-hub-view" data-hub-wallet="${key}" aria-pressed="${historyOpen&&key===kind}" aria-label="View ${label} history">View history <svg aria-hidden="true" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>${key==='proceed'?'<button class="btn primary small wallet-hub-action" data-hub-proceed>Proceed</button>':key==='cash'?'<button class="btn primary small wallet-hub-action" data-hub-transfer>Transfer MIO</button>':''}</div></article>`).join('');for(const b of $('incomeWalletCards').querySelectorAll('[data-hub-proceed],[data-hub-transfer]'))b.disabled=busy}
 function update(value,state={}){setIdentity(api?.identity());wallets=value;platinum=!!state.platinum;if(ensure()){cards();if(historyOpen&&$('page-wallet')?.classList.contains('active'))history.refresh()}}
 async function select(value){if(!kinds.some(([k])=>k===value))return;kind=value;if(!ensure())return;historyOpen=true;$('walletHubStatement').hidden=false;history.setWallet(kind);cards();await history.refresh()}
 async function freshWallets(){const owner=uid,ticket=epoch,r=await api.rpc('my_income_wallets');if(owner!==uid||ticket!==epoch)throw Error('Account changed. Please try again.');if(r.error)throw r.error;wallets=r.data;cards();return r.data}
 async function proceed(){if(busy||!uid)return;busy=true;cards();message('');const owner=uid,ticket=epoch;try{const w=await freshWallets(),minimum=Number(w.config?.minimum_mio??10),amount=Number(w.proceed_mio||0);if(amount<minimum&&!requestKey){message(`Insufficient balance. You need at least ${fmt(minimum)} MIO to proceed.`);return}const pin=await api.pin(requestKey?'confirming your previous Proceed request':`proceeding your full ${fmt(amount)} MIO balance`);if(!pin||owner!==uid||ticket!==epoch)return;requestKey ||= api.idKey();const r=await api.rpc('convert_all_proceed_wallet',{p_transaction_pin:pin,p_idempotency_key:requestKey});if(r.error)throw r.error;if(owner!==uid||ticket!==epoch)return;requestKey=null;await freshWallets();if(historyOpen)await history.refresh();message(`Balance proceeded successfully. ${fmt(r.data?.cash_amount)} MIO added to Cash Wallet.`)}catch(e){if(owner===uid&&ticket===epoch)message(e.message||'Could not proceed. Please try again.')}finally{if(owner===uid&&ticket===epoch){busy=false;cards()}}}
 function openTransfer(){if(busy||!uid)return;if(platinum){api.go('exchange');return}recipient=null;lookupTurn++;$('walletTransferForm').reset();$('walletTransferRecipient').textContent='Enter the Platinum member’s MIO ID.';$('walletTransferStatus').textContent='';$('walletTransferAvailable').textContent=fmt(wallets?.cash_mio)+' MIO';$('walletTransferConfirm').disabled=true;$('walletTransferDialog').showModal();$('walletTransferCode').focus()}
 async function lookup(){const code=$('walletTransferCode').value.trim(),ticket=++lookupTurn,owner=uid;recipient=null;$('walletTransferConfirm').disabled=true;if(!code){$('walletTransferRecipient').textContent='Enter the Platinum member’s MIO ID.';return}$('walletTransferRecipient').textContent='Verifying recipient…';try{const r=await api.rpc('lookup_transfer_recipient',{p_code:code});if(ticket!==lookupTurn||owner!==uid)return;if(r.error)throw r.error;const row=r.data?.[0];if(!row)throw Error('No eligible Platinum member found. Check the MIO ID.');recipient={...row,input:code};$('walletTransferRecipient').innerHTML=`<strong>✓ ${esc(row.full_name)}</strong><small>${esc(row.member_code)} · Verified Platinum account</small>`;$('walletTransferConfirm').disabled=false}catch(e){if(ticket===lookupTurn&&owner===uid)$('walletTransferRecipient').textContent=e.message}}
 async function transfer(e){e.preventDefault();if(busy||!uid)return;const form=e.target,amount=form.elements.amount.value,code=form.elements.code.value.trim();if(!recipient||recipient.input!==code)return;const peer={...recipient},owner=uid,ticket=epoch;if(!Number.isFinite(Number(amount))||Number(amount)<=0){$('walletTransferStatus').textContent='Enter a valid amount.';return}busy=true;$('walletTransferConfirm').disabled=true;let verified=false;try{const w=await freshWallets();if(Number(amount)>Number(w.cash_mio||0))throw Error('Insufficient Cash Wallet balance.');const check=await api.rpc('lookup_transfer_recipient',{p_code:peer.member_code});if(owner!==uid||ticket!==epoch)return;if(check.error)throw check.error;if(!check.data?.some(x=>x.member_code===peer.member_code&&x.full_name===peer.full_name))throw Error('Recipient changed. Please verify the MIO ID again.');$('walletTransferDialog').close();const pin=await api.pin(`transferring ${fmt(amount)} MIO to ${peer.full_name} (${peer.member_code})`);if(!pin||owner!==uid||ticket!==epoch)return;const signature=peer.member_code+':'+amount;if(signature!==transferSignature){transferSignature=signature;transferKey=api.idKey()}const r=await api.rpc('mio_transfer_to_member_code',{p_recipient_code:peer.member_code,p_amount:amount,p_transaction_pin:pin,p_idempotency_key:transferKey});if(r.error)throw r.error;if(owner!==uid||ticket!==epoch)return;verified=true;transferKey=null;transferSignature='';form.reset();recipient=null;await freshWallets();if(historyOpen)await history.refresh();message(`Transfer completed: ${fmt(amount)} MIO sent to ${peer.full_name}.`)}catch(e){if(owner===uid&&ticket===epoch){if($('walletTransferDialog').open)$('walletTransferStatus').textContent=e.message;else message(verified?'Transfer completed. Refresh to see the latest balance.':e.message)}}finally{if(owner===uid&&ticket===epoch){busy=false;cards();$('walletTransferConfirm').disabled=!recipient}}}
 function mount(options){api=options;document.body.insertAdjacentHTML('beforeend',`<dialog id="walletTransferDialog" class="wallet-transfer-dialog"><form id="walletTransferForm"><header><div><small>Cash Wallet</small><h2>Transfer to Platinum</h2></div><button type="button" data-close-wallet-transfer aria-label="Close transfer">×</button></header><p class="wallet-transfer-available">Available balance <strong id="walletTransferAvailable"></strong></p><label>Platinum MIO ID<input id="walletTransferCode" name="code" autocomplete="off" required placeholder="Enter MIO ID"></label><div id="walletTransferRecipient" class="wallet-verified-recipient" role="status"></div><label>Amount (MIO)<input name="amount" type="number" min="0.0001" step="0.0001" required placeholder="0.00"></label><p class="helper">Review the recipient and amount. Your transaction PIN is required next.</p><p id="walletTransferStatus" role="alert"></p><footer><button type="button" class="btn" data-close-wallet-transfer>Cancel</button><button id="walletTransferConfirm" class="btn primary" disabled>Continue</button></footer></form></dialog>`);$('walletTransferForm').addEventListener('submit',transfer);$('walletTransferCode').addEventListener('input',()=>{recipient=null;lookupTurn++;$('walletTransferConfirm').disabled=true;clearTimeout(lookupTimer);lookupTimer=setTimeout(lookup,350)});$('walletTransferCode').addEventListener('blur',()=>{clearTimeout(lookupTimer);lookup()});$('walletTransferDialog').addEventListener('close',()=>{lookupTurn++});document.addEventListener('click',e=>{const b=e.target.closest('[data-hub-wallet],[data-hub-proceed],[data-hub-transfer],[data-close-wallet-transfer]');if(!b)return;if(b.hasAttribute('data-close-wallet-transfer')){$('walletTransferDialog').close();return}if(b.dataset.hubWallet){select(b.dataset.hubWallet);return}if(b.hasAttribute('data-hub-proceed'))proceed();else openTransfer()});ensure()}
 function enter(){historyOpen=false;if(ensure()){$('walletHubStatement').hidden=true;history.setWallet(kind);cards();message('')}}
 return {mount,update,select,setIdentity,enter,refresh:()=>historyOpen?history?.refresh():Promise.resolve()};
})();
